# hypothesis: a class whose __iter__ exists only as an annotation cannot be iterated, since for-loops look special methods up on the type and raise TypeError, so a checker that accepts the loop is unsound; a class with a real __iter__ is a working control.
from collections.abc import Callable, Iterator


class Bag:
    __iter__: Callable[[], Iterator[int]]  # annotation only, no method

    def size(self) -> int:
        return 2


class Counted:
    def __init__(self, n: int) -> None:
        self.n = n

    def __iter__(self) -> Iterator[int]:
        return iter(range(self.n))


def probe_iter() -> str:
    bag = Bag()
    try:
        for item in bag:  # expect-error: Bag is not iterable
            print(item)
    except TypeError:
        return 'TypeError'
    return 'iterated'


print(Bag().size())
print(probe_iter())
print(list(Counted(3)))
